<main class="main" data-template-settings="<?= e($template['settings_json']??'{}') ?>"><div class="main__inner"><div class="settings-page report-template-page"><header class="settings-page__header"><div><nav class="breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><span>General Settings</span><i data-lucide="chevron-right"></i><span>Report Templates</span></nav><h1>Report Templates</h1><p>Control official PDF presentation without exposing code or custom CSS.</p></div><a class="btn btn--secondary" target="_blank" href="<?= url('/admin/settings/report-templates/'.rawurlencode($selectedType).'/preview') ?>"><i data-lucide="eye"></i>Preview PDF</a></header>
<div class="report-template-layout"><aside class="settings-card report-type-list"><?php foreach($types as$key=>$label):?><a class="report-type-link<?= $selectedType===$key?' is-active':'' ?>" href="<?= url('/admin/settings/report-templates?type='.rawurlencode($key)) ?>"><i data-lucide="file-text"></i><span><?= e($label) ?></span></a><?php endforeach?></aside>
<form class="settings-card" method="post" action="<?= url('/admin/settings/report-templates/'.rawurlencode($selectedType)) ?>"><?= csrf_field() ?><header class="settings-card__header"><div><span class="section-kicker">Selected document</span><h2><?= e($types[$selectedType]) ?></h2><p>Changes affect presentation only; report data remains read-only.</p></div></header><div class="settings-card__body"><div class="settings-grid"><div class="form-field"><label class="form-label">Document Title</label><input class="form-input" name="title" maxlength="120" value="<?= e($template['title']) ?>" required></div><div class="form-field"><label class="form-label">Subtitle</label><input class="form-input" name="subtitle" maxlength="255" value="<?= e($template['subtitle']) ?>"></div><div class="form-field form-field--wide"><label class="form-label">Introductory Text</label><textarea class="form-input form-textarea" name="body_html" rows="5"><?= e($template['body_html']) ?></textarea><p class="field-hint">Basic paragraphs, headings, bold, italic and lists are allowed.</p></div><div class="form-field form-field--wide"><label class="form-label">Footer Note</label><input class="form-input" name="footer_text" maxlength="500" value="<?= e($template['footer_text']) ?>"></div><div class="form-field"><label class="form-label">Page Size</label><select class="form-select" name="page_size"><option <?= $template['page_size']==='A4'?'selected':'' ?>>A4</option><option <?= $template['page_size']==='Letter'?'selected':'' ?>>Letter</option></select></div><div class="form-field"><label class="form-label">Orientation</label><select class="form-select" name="page_orientation"><option value="P" <?= $template['page_orientation']==='P'?'selected':'' ?>>Portrait</option><option value="L" <?= $template['page_orientation']==='L'?'selected':'' ?>>Landscape</option></select></div><div class="form-field"><label class="form-label">Margins</label><select class="form-select" name="margin_mode"><option value="normal" <?= $template['margin_mode']==='normal'?'selected':'' ?>>Normal</option><option value="compact" <?= $template['margin_mode']==='compact'?'selected':'' ?>>Compact</option></select></div><div class="form-field"><label class="form-label">Primary Color</label><input class="form-input" type="color" name="primary_color" value="<?= e($template['primary_color']) ?>"></div><div class="form-field"><label class="form-label">Accent Color</label><input class="form-input" type="color" name="accent_color" value="<?= e($template['accent_color']) ?>"></div></div><div class="template-toggles"><?php foreach(['show_logo'=>'Institute Logo','show_address'=>'Address','show_phone'=>'Phone','show_website'=>'Website','show_generated_date'=>'Generated Date','show_page_numbers'=>'Page Numbers']as$key=>$label):?><label class="check-row"><input type="checkbox" name="<?= $key ?>" value="1" <?= !empty($template[$key])?'checked':'' ?>><?= e($label) ?></label><?php endforeach?></div><div class="inline-info"><i data-lucide="braces"></i><span>Allowed placeholders: <?= e($placeholders?implode(', ',array_map(fn($x)=>'{{'.$x.'}}',$placeholders)):'None') ?></span></div></div><footer class="settings-card__footer"><button class="btn btn--primary" type="submit"><i data-lucide="save"></i>Save Template</button></footer></form></div><form method="post" action="<?= url('/admin/settings/report-templates/'.rawurlencode($selectedType).'/reset') ?>" onsubmit="return confirm('Reset this report template to its default settings?')"><?= csrf_field() ?><button class="btn btn--secondary" type="submit"><i data-lucide="rotate-ccw"></i>Reset to Default</button></form></div></div></main>
